package org.ruoyi.service.lawyer;

import com.fasterxml.jackson.core.type.TypeReference;
import com.fasterxml.jackson.databind.ObjectMapper;
import lombok.RequiredArgsConstructor;
import org.ruoyi.common.core.exception.ServiceException;
import org.ruoyi.domain.entity.lawyer.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.support.TransactionTemplate;
import java.util.*;

@Service @RequiredArgsConstructor
public class DossierClaimService {
    private final JdbcTemplate jdbc;
    private final TransactionTemplate tx;
    private final DossierAnchorService anchors;
    private static final ObjectMapper JSON=new ObjectMapper().findAndRegisterModules();
    public record Filter(String search,String kind,String status,String group,String fileVersionId,String reviewerId,String from,String to,Integer pageNum,Integer pageSize){}
    public record Edit(int expectedVersion,String kind,String text,Map<String,String> values,List<DossierClaimSchema.Link> sources,String reviewStatus,String reason){}
    public record Combine(List<Long> ids,List<Integer> versions,String text,String reason){}
    public record Split(int expectedVersion,List<Edit> parts,String reason){}
    public record Decision(int expectedVersion,int claimVersion,String decision,String reason){}
    public record Detail(CaseClaim claim,List<DossierAnchorService.Resolved> sources,List<Map<String,Object>> links,List<Map<String,Object>> suggestions,List<Map<String,Object>> history){}
    public record Listing(List<CaseClaim> rows,long total,Map<String,Long> groups){}
    CaseClaim get(DossierAnchorService.Principal p,Long id,boolean lock){anchors.owned(p);var rows=jdbc.query("SELECT * FROM lawyer_case_claim WHERE id=? AND tenant_id=? AND case_id=? AND user_id=?"+(lock?" FOR UPDATE":""),DossierMaterialService.mapping(CaseClaim.class),id,p.tenantId(),p.caseId(),p.userId());if(rows.isEmpty())throw new ServiceException("候选不可用",404);return rows.get(0);}
    List<Map<String,Object>> links(DossierAnchorService.Principal p,Long id){return jdbc.queryForList("SELECT CAST(anchor_id AS CHAR) anchorId,relation FROM lawyer_case_claim_source WHERE tenant_id=? AND case_id=? AND claim_id=? ORDER BY anchor_id,relation",p.tenantId(),p.caseId(),id);}
    List<String> sourceErrors(DossierAnchorService.Principal p,List<DossierClaimSchema.Link> links,boolean original){var errors=new ArrayList<String>();if(links==null||links.isEmpty())return new ArrayList<>(List.of("NO_SOURCE"));if(links.stream().noneMatch(l->"supports".equals(l.relation())))errors.add("NO_SUPPORTING_SOURCE");for(var link:links)try{if(!DossierClaimSchema.RELATIONS.contains(link.relation()))throw new IllegalArgumentException();var resolved=anchors.resolve(p,Long.valueOf(link.anchorId()),original);if(!resolved.verified())errors.add(Objects.toString(resolved.error(),"SOURCE_UNVERIFIED"));}catch(Exception e){errors.add("SOURCE_UNAVAILABLE");}return errors.stream().distinct().toList();}
    List<DossierClaimSchema.Link> linkValues(DossierAnchorService.Principal p,Long id){return links(p,id).stream().map(l->new DossierClaimSchema.Link(l.get("anchorId").toString(),l.get("relation").toString())).toList();}
    CaseClaim refresh(DossierAnchorService.Principal p,CaseClaim claim,boolean original){
        var errors=new ArrayList<>(sourceErrors(p,linkValues(p,claim.getId()),original));
        if(!Boolean.TRUE.equals(claim.getEdited()))errors.addAll(BankStatementService.strings(claim.getSourceErrors()));
        errors=new ArrayList<>(new LinkedHashSet<>(errors));boolean verified=errors.isEmpty();
        String state=!verified&&"confirmed".equals(claim.getReviewStatus())?"stale":claim.getReviewStatus();
        String sourceStatus=verified?"verified":"source_unverified",errorJson=BankStatementService.json(errors);
        if(Objects.equals(state,claim.getReviewStatus())&&Objects.equals(sourceStatus,claim.getSourceStatus())&&errorJson.equals(claim.getSourceErrors()))return claim;
        return tx.execute(s->{anchors.owned(p);var before=get(p,claim.getId(),true);
            if(!before.getVersion().equals(claim.getVersion()))return refresh(p,before,original);
            int changed=jdbc.update("UPDATE lawyer_case_claim SET source_status=?,source_errors=?,review_status=?,version=version+1,update_time=UTC_TIMESTAMP() WHERE id=? AND version=?",sourceStatus,errorJson,state,claim.getId(),claim.getVersion());
            var after=get(p,claim.getId(),false);
            if(changed==1)audit(p,claim.getId(),"source_dependency",before,after,"服务器回查材料版本、页文本或出处指纹变化；历史确认保留但当前需再核对");
            return after;
        });
    }
    public Detail detail(Long caseId,Long id){var p=anchors.principal(caseId);var c=refresh(p,get(p,id,false),true);var sources=new ArrayList<DossierAnchorService.Resolved>();for(var l:linkValues(p,id))try{sources.add(anchors.resolve(p,Long.valueOf(l.anchorId()),true));}catch(ServiceException ignored){}return new Detail(c,sources,links(p,id),suggestions(p,id),history(p,id));}
    public Listing list(Long caseId,Filter f){var p=anchors.principal(caseId);var all=jdbc.query("SELECT * FROM lawyer_case_claim WHERE tenant_id=? AND case_id=? AND user_id=? ORDER BY create_time DESC,id DESC LIMIT 3001",DossierMaterialService.mapping(CaseClaim.class),p.tenantId(),caseId,p.userId());if(all.size()>3000)throw new ServiceException("候选超过单次核对范围，请按案件归档整理",422);all=all.stream().map(c->refresh(p,c,false)).toList();var groups=new LinkedHashMap<String,Long>();for(var c:all)groups.merge(group(c),1L,Long::sum);final var filter=f==null?new Filter(null,null,null,null,null,null,null,null,1,25):f;var selected=all.stream().filter(c->blank(filter.search())||c.getClaimText().toLowerCase(Locale.ROOT).contains(filter.search().toLowerCase(Locale.ROOT))||c.getOriginalText().toLowerCase(Locale.ROOT).contains(filter.search().toLowerCase(Locale.ROOT))).filter(c->blank(filter.kind())||filter.kind().equals(c.getKind())).filter(c->blank(filter.status())||filter.status().equals(c.getReviewStatus())).filter(c->blank(filter.group())||filter.group().equals(group(c))).filter(c->blank(filter.reviewerId())||Objects.toString(c.getReviewerId(),"").equals(filter.reviewerId())).filter(c->blank(filter.fileVersionId())||links(p,c.getId()).stream().anyMatch(l->{try{return anchors.get(p,Long.valueOf(l.get("anchorId").toString())).getFileVersionId().toString().equals(filter.fileVersionId());}catch(Exception e){return false;}})).filter(c->dateRange(c,filter.from(),filter.to())).sorted(Comparator.comparingInt(c->priority(group(c)))).toList();int page=Math.max(1,Objects.requireNonNullElse(filter.pageNum(),1)),size=Math.min(100,Math.max(1,Objects.requireNonNullElse(filter.pageSize(),25)));return new Listing(selected.stream().skip((long)(page-1)*size).limit(size).toList(),selected.size(),groups);}
    static boolean blank(String v){return v==null||v.isBlank();}
    static boolean dateRange(CaseClaim c,String from,String to){String date=c.getCreateTime().toInstant().atZone(java.time.ZoneOffset.UTC).toLocalDate().toString();try{if(!blank(from))java.time.LocalDate.parse(from);if(!blank(to))java.time.LocalDate.parse(to);}catch(Exception e){throw new ServiceException("创建日期筛选无效",400);}return (blank(from)||date.compareTo(from)>=0)&&(blank(to)||date.compareTo(to)<=0);}
    static String group(CaseClaim c){if(Set.of("confirmed","excluded").contains(c.getReviewStatus()))return c.getReviewStatus();if(!"verified".equals(c.getSourceStatus()))return "source_unverified";return "high".equals(c.getRisk())?"high_risk":"pending";}
    static int priority(String group){return List.of("high_risk","source_unverified","pending","confirmed","excluded").indexOf(group);}
    static void validate(Edit e){if(e==null||e.kind()==null||!DossierClaimSchema.KINDS.contains(e.kind())||e.text()==null||e.text().isBlank()||e.text().length()>3000||e.sources()==null||e.sources().size()>20||e.values()==null||e.values().size()>7||!Set.of("dateRaw","amountRaw","name","currency","datePrecision","dateStart","dateEnd").containsAll(e.values().keySet())||e.values().values().stream().anyMatch(v->v!=null&&v.length()>200)||!Set.of("pending_review","confirmed","excluded").contains(Objects.toString(e.reviewStatus(),"")))throw new ServiceException("候选字段或状态无效",400);BankStatementService.reason(e.reason());for(var l:e.sources())if(l==null||l.anchorId()==null||!l.anchorId().matches("[1-9][0-9]{0,18}")||!DossierClaimSchema.RELATIONS.contains(Objects.toString(l.relation(),"")))throw new ServiceException("来源关联无效",400);}
    static String risk(String kind,Map<String,String> values){return Set.of("date","payment","subject","contradiction").contains(kind)||values.values().stream().anyMatch(v->v!=null&&!v.isBlank())?"high":"normal";}
    static String risk(String kind,Map<String,String> values,String text){return "high".equals(risk(kind,values))||text.matches("(?s).*(?:[0-9]{4}[-年/][0-9]{1,2}|[0-9]+[.,][0-9]+|[0-9]{15,18}|金额|付款|支付|身份证).* ".stripTrailing())?"high":"normal";}
    void replaceLinks(DossierAnchorService.Principal p,Long id,List<DossierClaimSchema.Link> links){jdbc.update("DELETE FROM lawyer_case_claim_source WHERE claim_id=? AND tenant_id=? AND case_id=?",id,p.tenantId(),p.caseId());for(var l:new LinkedHashSet<>(links)){anchors.get(p,Long.valueOf(l.anchorId()));jdbc.update("INSERT INTO lawyer_case_claim_source(id,tenant_id,case_id,claim_id,anchor_id,relation,create_by,create_time) VALUES(?,?,?,?,?,?,?,UTC_TIMESTAMP())",DossierMaterialService.id(),p.tenantId(),p.caseId(),id,Long.valueOf(l.anchorId()),l.relation(),p.userId());}}
    void audit(DossierAnchorService.Principal p,Long id,String action,Object before,Object after,String reason){jdbc.update("INSERT INTO lawyer_case_review_change(id,tenant_id,case_id,object_kind,object_id,action,before_json,after_json,reason,operator_id,create_time) VALUES(?,?,?,'claim',?,?,?,?,?,?,UTC_TIMESTAMP())",DossierMaterialService.id(),p.tenantId(),p.caseId(),id,action,BankStatementService.json(before),BankStatementService.json(after),reason,p.userId());}
    public CaseClaim manual(Long caseId,Edit e){var p=anchors.principal(caseId);validate(e);if(!"pending_review".equals(e.reviewStatus()))throw new ServiceException("新建事实先保存待核，再逐项核对",400);return tx.execute(s->insertManual(p,e));}
    CaseClaim insertManual(DossierAnchorService.Principal p,Edit e){var errors=sourceErrors(p,e.sources(),true);for(var l:e.sources())anchors.get(p,Long.valueOf(l.anchorId()));long id=DossierMaterialService.id();String original=e.sources().stream().map(l->anchors.get(p,Long.valueOf(l.anchorId())).getFragmentText()).distinct().reduce((a,b)->a+"\n"+b).orElse("");if(original.length()>20000)throw new ServiceException("原文总长超限，请拆分事实",422);jdbc.update("INSERT INTO lawyer_case_claim(id,tenant_id,case_id,user_id,kind,claim_text,original_text,values_json,risk,source_status,source_errors,edited,create_by,create_time,update_time) VALUES(?,?,?,?,?,?,?,?,?,?,?,1,?,UTC_TIMESTAMP(),UTC_TIMESTAMP())",id,p.tenantId(),p.caseId(),p.userId(),e.kind(),e.text(),original,BankStatementService.json(e.values()),risk(e.kind(),e.values(),e.text()),errors.isEmpty()?"verified":"source_unverified",BankStatementService.json(errors),p.userId());replaceLinks(p,id,e.sources());var out=get(p,id,false);audit(p,id,"manual_create",Map.of(),out,e.reason());return out;}
    public CaseClaim edit(Long caseId,Long id,Edit e){var p=anchors.principal(caseId);validate(e);return tx.execute(s->edit(p,id,e));}
    CaseClaim edit(DossierAnchorService.Principal p,Long id,Edit e){var before=get(p,id,true);if(before.getVersion()!=e.expectedVersion())throw new ServiceException("候选已被修改，请对照最新版本；当前输入保留",409);var errors=sourceErrors(p,e.sources(),true);if("confirmed".equals(e.reviewStatus())){if(!errors.isEmpty())throw new ServiceException("无有效来源不能确认："+String.join(",",errors),422);String amount=e.values().get("amountRaw"),date=e.values().get("dateRaw");if((!blank(amount)&&BankStatementParser.money(amount)==null)||("payment".equals(e.kind())&&(BankStatementParser.money(amount)==null||blank(e.values().get("currency")))))throw new ServiceException("金额/币种尚未核对明确",422);DossierReviewDate.validate(e.values(),"date".equals(e.kind()));}
        var beforeLinks=linkValues(p,id);replaceLinks(p,id,e.sources());int changed=jdbc.update("UPDATE lawyer_case_claim SET kind=?,claim_text=?,values_json=?,risk=?,review_status=?,source_status=?,source_errors=?,edited=1,version=version+1,reviewer_id=?,reviewed_at=UTC_TIMESTAMP(),update_by=?,update_time=UTC_TIMESTAMP() WHERE id=? AND version=?",e.kind(),e.text(),BankStatementService.json(e.values()),risk(e.kind(),e.values(),e.text()),e.reviewStatus(),errors.isEmpty()?"verified":"source_unverified",BankStatementService.json(errors),p.userId(),p.userId(),id,e.expectedVersion());if(changed!=1)throw new ServiceException("版本冲突，输入保留",409);var after=get(p,id,false);audit(p,id,"edit",Map.of("claim",before,"sources",beforeLinks),Map.of("claim",after,"sources",e.sources()),e.reason());return after;
    }
    public List<CaseClaim> split(Long caseId,Long id,Split split){var p=anchors.principal(caseId);BankStatementService.reason(split.reason());if(split.parts()==null||split.parts().size()<2||split.parts().size()>20)throw new ServiceException("拆分需2～20项",400);return tx.execute(s->{var parent=get(p,id,true);if(parent.getVersion()!=split.expectedVersion())throw new ServiceException("版本冲突",409);var out=new ArrayList<CaseClaim>();for(var e:split.parts()){validate(e);if(!"pending_review".equals(e.reviewStatus()))throw new ServiceException("拆分子项必须待核",400);out.add(insertManual(p,e));}edit(p,id,new Edit(parent.getVersion(),parent.getKind(),parent.getClaimText(),values(parent),linkValues(p,id),"excluded",split.reason()));return out;});}
    public CaseClaim merge(Long caseId,Combine request){var p=anchors.principal(caseId);BankStatementService.reason(request.reason());if(request.ids()==null||request.versions()==null||request.ids().size()<2||request.ids().size()>20||request.ids().size()!=request.versions().size()||new HashSet<>(request.ids()).size()!=request.ids().size())throw new ServiceException("合并需2～20个不同候选及版本",400);return tx.execute(s->{var rows=new ArrayList<CaseClaim>();var sources=new LinkedHashSet<DossierClaimSchema.Link>();for(int i=0;i<request.ids().size();i++){var c=get(p,request.ids().get(i),true);if(c.getVersion().intValue()!=request.versions().get(i))throw new ServiceException("合并版本冲突",409);rows.add(c);sources.addAll(linkValues(p,c.getId()));}var e=new Edit(1,"other",request.text(),new LinkedHashMap<>(),new ArrayList<>(sources),"pending_review",request.reason());validate(e);var out=insertManual(p,e);for(var c:rows)edit(p,c.getId(),new Edit(c.getVersion(),c.getKind(),c.getClaimText(),values(c),linkValues(p,c.getId()),"excluded",request.reason()));return out;});}
    static Map<String,String> values(CaseClaim c){try{return JSON.readValue(c.getValuesJson(),new TypeReference<LinkedHashMap<String,String>>(){});}catch(Exception e){throw new ServiceException("候选字段存储无效",422);}}
    void importCandidate(DossierAnchorService.Principal p,Long run,DossierClaimSchema.Candidate candidate,Set<String> offered,int index,List<String> rejections){
        var errors=new ArrayList<String>();var valid=new ArrayList<DossierClaimSchema.Link>();boolean quote=false;
        for(var link:candidate.sources()){
            if(!offered.contains(link.anchorId())){errors.add("ANCHOR_NOT_OFFERED");continue;}
            try{var source=anchors.resolve(p,Long.valueOf(link.anchorId()),true);if(!source.verified()){errors.add(Objects.toString(source.error(),"SOURCE_UNVERIFIED"));continue;}valid.add(link);if(source.anchor().getFragmentText().contains(candidate.originalText()))quote=true;}catch(Exception e){errors.add("SOURCE_UNAVAILABLE");}
        }
        errors.addAll(sourceErrors(p,valid,true));if(!quote)errors.add("ORIGINAL_EXCERPT_MISMATCH");
        String origin=DossierAnchorService.hash(BankStatementService.json(List.of(candidate.kind(),candidate.originalText(),candidate.sources().stream().map(DossierClaimSchema.Link::anchorId).sorted().toList(),index)));
        var existing=jdbc.query("SELECT * FROM lawyer_case_claim WHERE tenant_id=? AND case_id=? AND origin_key=? FOR UPDATE",DossierMaterialService.mapping(CaseClaim.class),p.tenantId(),p.caseId(),origin);
        var proposal=new LinkedHashMap<String,Object>();proposal.put("candidate",candidate);proposal.put("offeredAnchors",offered.stream().sorted().toList());proposal.put("sourceErrors",errors.stream().distinct().toList());
        if(!existing.isEmpty()){
            var old=existing.get(0);jdbc.update("INSERT INTO lawyer_case_claim_suggestion(id,tenant_id,case_id,claim_id,run_id,proposed_json,create_time,update_time) VALUES(?,?,?,?,?,?,UTC_TIMESTAMP(),UTC_TIMESTAMP())",DossierMaterialService.id(),p.tenantId(),p.caseId(),old.getId(),run,BankStatementService.json(proposal));
            // No AI rerun writes old text, values, sources, review state or reviewer, even for pending rows.
        }else{
            long id=DossierMaterialService.id();jdbc.update("INSERT INTO lawyer_case_claim(id,tenant_id,case_id,user_id,kind,claim_text,original_text,values_json,risk,source_status,source_errors,origin_key,last_run_id,create_by,create_time,update_time) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,UTC_TIMESTAMP(),UTC_TIMESTAMP())",id,p.tenantId(),p.caseId(),p.userId(),candidate.kind(),candidate.text(),candidate.originalText(),BankStatementService.json(candidate.values()),"high".equals(candidate.risk())?"high":risk(candidate.kind(),candidate.values(),candidate.text()),errors.isEmpty()?"verified":"source_unverified",BankStatementService.json(errors.stream().distinct().toList()),origin,run,p.userId());replaceLinks(p,id,valid);audit(p,id,"model_candidate",Map.of(),get(p,id,false),"模型结构化建议，仅待人工核对；运行"+run);
        }
        rejections.addAll(errors.stream().distinct().toList());
    }
    public CaseClaim decideSuggestion(Long caseId,Long id,Long suggestionId,Decision request){var p=anchors.principal(caseId);BankStatementService.reason(request.reason());if(!Set.of("adopt","dismiss").contains(Objects.toString(request.decision(),"")))throw new ServiceException("建议决定无效",400);return tx.execute(s->{var old=get(p,id,true);if(old.getVersion()!=request.claimVersion())throw new ServiceException("候选版本已变化，当前输入保留",409);var rows=jdbc.queryForList("SELECT * FROM lawyer_case_claim_suggestion WHERE id=? AND claim_id=? AND tenant_id=? AND case_id=? FOR UPDATE",suggestionId,id,p.tenantId(),caseId);if(rows.isEmpty())throw new ServiceException("建议不可用",404);var proposal=rows.get(0);if(!"pending".equals(proposal.get("state"))||((Number)proposal.get("version")).intValue()!=request.expectedVersion())throw new ServiceException("建议已处理或版本冲突",409);
            if("adopt".equals(request.decision()))try{var tree=JSON.readTree(proposal.get("proposed_json").toString());var candidate=JSON.treeToValue(tree.get("candidate"),DossierClaimSchema.Candidate.class);var offered=new HashSet<>(ids(tree.get("offeredAnchors")));if(candidate.sources().stream().anyMatch(l->!offered.contains(l.anchorId()))||!tree.get("sourceErrors").isEmpty())throw new ServiceException("来源未验证建议不能直接采纳，请先人工修正来源",422);edit(p,id,new Edit(old.getVersion(),candidate.kind(),candidate.text(),candidate.values(),candidate.sources(),"pending_review",request.reason()));}catch(ServiceException e){throw e;}catch(Exception e){throw new ServiceException("建议结构无效",422);}
            jdbc.update("UPDATE lawyer_case_claim_suggestion SET state=?,operator_id=?,reason=?,version=version+1,update_time=UTC_TIMESTAMP() WHERE id=?",request.decision().equals("adopt")?"adopted":"dismissed",p.userId(),request.reason(),suggestionId);audit(p,id,"suggestion_"+request.decision(),Map.of("suggestionId",suggestionId.toString(),"state","pending"),Map.of("suggestionId",suggestionId.toString(),"state",request.decision()),request.reason());return get(p,id,false);
        });}
    private static List<String> ids(com.fasterxml.jackson.databind.JsonNode node){var out=new ArrayList<String>();if(node!=null&&node.isArray())node.forEach(n->out.add(n.asText()));return out;}
    List<Map<String,Object>> suggestions(DossierAnchorService.Principal p,Long id){return jdbc.queryForList("SELECT CAST(id AS CHAR) id,CAST(run_id AS CHAR) runId,proposed_json proposedJson,state,version,DATE_FORMAT(create_time,'%Y-%m-%dT%H:%i:%sZ') createTime FROM lawyer_case_claim_suggestion WHERE tenant_id=? AND case_id=? AND claim_id=? ORDER BY create_time DESC,id DESC",p.tenantId(),p.caseId(),id);}
    List<Map<String,Object>> history(DossierAnchorService.Principal p,Long id){var rows=jdbc.queryForList("SELECT CAST(id AS CHAR) id,action,before_json beforeJson,after_json afterJson,reason,CAST(operator_id AS CHAR) operatorId,DATE_FORMAT(create_time,'%Y-%m-%dT%H:%i:%sZ') createTime FROM lawyer_case_review_change WHERE tenant_id=? AND case_id=? AND object_kind='claim' AND object_id=? ORDER BY create_time,id",p.tenantId(),p.caseId(),id);for(var row:rows)for(String key:List.of("beforeJson","afterJson","reason"))if(row.get(key) instanceof String text)row.put(key,BankStatementParser.safeText(text));return rows;}
}
